constraints:
1 <= Number of Nodes <= 10^{3}

expected time complexity: O(N^2)
expected auxiliary space: O(N), where N indicates number of nodes.

standard_solution_code:
class Node:

	def __init__(self, value):
		self.data = value
		self.left = None
		self.right = None

class Solution:

	def constructBinaryTree(self, pre, preM, n):
		self.i = 0
		return self.util(pre, preM, n)

	def util(self, pre, preM, n):
		if self.i == n:
			return None
		j = 0
		while j < n:
			if preM[j] == pre[self.i]:
				break
			j += 1
		preM[j] = -1
		root = Node(pre[self.i])
		self.i += 1
		if j == n - 1 or preM[j + 1] == -1:
			return root
		root.left = self.util(pre, preM, n)
		root.right = self.util(pre, preM, n)
		return root
